// Checker type -> PropType-like JSON, using ONLY structured API calls. typeToString is never used for structure.
export const TF = { Any:1,Unknown:2,Undefined:4,Null:8,Void:16,String:32,Number:64,BigInt:128,Boolean:256,ESSymbol:512,StringLiteral:1024,NumberLiteral:2048,BigIntLiteral:4096,BooleanLiteral:8192,UniqueESSymbol:16384,EnumLiteral:32768,Enum:65536,NonPrimitive:131072,Never:262144,TypeParameter:524288,Object:1048576,Index:2097152,TemplateLiteral:4194304,StringMapping:8388608,Substitution:16777216,IndexedAccess:33554432,Conditional:67108864,Union:134217728,Intersection:268435456 };
export const OF = { Class:1, Interface:2, Reference:4, Tuple:8, Anonymous:16, Mapped:32, Instantiated:64 };
export const SF = { Property:4, EnumMember:8, Function:16, Class:32, Interface:64, Method:8192, GetAccessor:32768, SetAccessor:65536, TypeAlias:524288, Alias:2097152, Optional:16777216 };
export const EF = { Required:1, Optional:2, Rest:4, Variadic:8 };
const MAX_DEPTH = 5;
const MAX_FIELDS = 40;  // past this an object below the top level is a named ref plus a count
const MAX_UNION = 120;

export function makeConverter(checker, stats) {
  const memo = new Map(); // type id -> json (depth-0 results only) : ids are stable inside one snapshot
  const bump = (k) => (stats[k] = (stats[k] ?? 0) + 1);
  function nameOf(t) {
    const a = t.getAliasSymbol(); if (a) return { name: a.name, via: 'alias', sym: a };
    const s = t.getSymbol(); if (s && s.name !== '__type' && s.name !== '__object') return { name: s.name, via: 'symbol', sym: s };
    return null;
  }
  function params(sig) {
    const ps = sig.getParameters();
    const out = [];
    const rest = sig.hasRestParameter;
    ps.forEach((p, i) => {
      let optional = false;
      const d = p.valueDeclaration;
      if (d) { const n = d.resolve(); optional = !!n?.questionToken || !!n?.initializer; bump('declResolve'); }
      out.push({ name: p.name, type: conv(checker.getTypeOfSymbol(p), 1, new Set()), optional, rest: rest && i === ps.length - 1 });
    });
    return out;
  }
  function fnJson(sig, depth, seen) {
    const tps = sig.getTypeParameters().map((x) => x.getSymbol()?.name);
    return { kind: 'function', typeParams: tps, params: params(sig), returnType: conv(sig.getReturnType(), depth + 1, seen) };
  }
  function conv(t, depth = 0, seen = new Set()) {
    const f = t.flags;
    if (depth > MAX_DEPTH) return { kind: 'opaque', reason: 'depth' };
    if (f & TF.Any) return { kind: 'any' };
    if (f & TF.Unknown) return { kind: 'unknown' };
    if (f & TF.Never) return { kind: 'never' };
    if (f & TF.Void) return { kind: 'void' };
    if (f & TF.Undefined) return { kind: 'undefined' };
    if (f & TF.Null) return { kind: 'null' };
    if (f & TF.Boolean) return { kind: 'boolean' };
    if (f & TF.EnumLiteral && f & (TF.StringLiteral | TF.NumberLiteral)) { const s = t.getSymbol(); const par = s?.getParent(); return { kind: 'enumMember', enum: par?.name, member: s?.name, value: t.value }; }
    if (f & TF.StringLiteral) return { kind: 'stringLiteral', value: t.value };
    if (f & TF.NumberLiteral) return { kind: 'numberLiteral', value: t.value };
    if (f & TF.BooleanLiteral) return { kind: 'boolLiteral', value: t.value === true };
    if (f & TF.BigIntLiteral) return { kind: 'bigintLiteral', value: String(t.value?.base10Value ?? t.value) };
    if (f & TF.String) return { kind: 'string' };
    if (f & TF.Number) return { kind: 'number' };
    if (f & TF.BigInt) return { kind: 'bigint' };
    if (f & TF.UniqueESSymbol) return { kind: 'uniqueSymbol', name: t.getSymbol()?.name };
    if (f & TF.ESSymbol) return { kind: 'symbol' };
    if (f & TF.NonPrimitive) return { kind: 'object' };
    if (f & TF.TypeParameter) { const c = t.getConstraint(); const d = t.getDefault(); return { kind: 'typeParam', name: t.getSymbol()?.name, constraint: c ? conv(c, depth + 1, seen) : undefined, default: d ? conv(d, depth + 1, seen) : undefined, isThis: t.isThisType || undefined }; }
    if (f & TF.TemplateLiteral) return { kind: 'template', texts: t.texts, types: t.getTypes?.()?.map((x) => conv(x, depth + 1, seen)) };
    if (f & TF.StringMapping) { return { kind: 'stringMapping', name: t.getSymbol()?.name, base: conv(t.getTypes()?.[0] ?? t.getBaseType?.(), depth + 1, seen) }; }
    if (f & TF.Index) return { kind: 'keyof', target: conv(t.getObjectType?.() ?? t.getTypes()[0], depth + 1, seen) };
    if (f & TF.IndexedAccess) return { kind: 'indexedAccess', object: conv(t.getObjectType(), depth + 1, seen), index: conv(t.getIndexType(), depth + 1, seen) };
    if (f & TF.Conditional) return { kind: 'conditional', check: conv(t.getCheckType(), depth + 1, seen), extends: conv(t.getExtendsType(), depth + 1, seen), then: conv(t.getTrueType(), depth + 1, seen), else: conv(t.getFalseType(), depth + 1, seen) };
    if (f & TF.Substitution) return conv(t.getBaseType(), depth, seen);
    if (f & (TF.Union | TF.Intersection)) {
      const ms = t.getTypes() ?? [];
      const alias = t.getAliasSymbol();
      if (depth > 0 && ms.length > MAX_UNION) { bump('truncatedUnions'); return { kind: 'named', name: t.getAliasSymbol()?.name ?? '(union)', args: [], truncated: ms.length }; }
      let members = ms.map((m) => conv(m, depth + 1, seen));
      if (f & TF.Union && members.some((m) => m.kind === 'boolLiteral' && m.value) && members.some((m) => m.kind === 'boolLiteral' && !m.value)) { const i = members.findIndex((m) => m.kind === 'boolLiteral'); members = members.filter((m) => m.kind !== 'boolLiteral'); members.splice(i, 0, { kind: 'boolean' }); }
      return { kind: f & TF.Union ? 'union' : 'intersection', members, alias: alias?.name };
    }
    if (f & TF.Object) {
      const of = t.objectFlags;
      const key = t.id;
      if (seen.has(key)) return { kind: 'recursive', name: nameOf(t)?.name };
      const seen2 = new Set(seen).add(key);
      if ((of & OF.Reference) && checker.isTupleType(t)) {
        const args = checker.getTypeArguments(t);
        const target = t.getTarget();
        const ef = target.elementFlags ?? [];
        return { kind: 'tuple', readonly: target.readonly, elements: args.map((a, i) => ({ type: conv(a, depth + 1, seen2), optional: !!((ef[i] ?? 1) & EF.Optional), rest: !!((ef[i] ?? 1) & (EF.Rest | EF.Variadic)) })) };
      }
      if ((of & OF.Reference) && checker.isArrayType(t)) { const [el] = checker.getTypeArguments(t); return { kind: 'array', element: conv(el, depth + 1, seen2), readonly: t.getSymbol()?.name === 'ReadonlyArray' || undefined }; }
      const nm = nameOf(t);
      const calls = t.getCallSignatures(), cons = t.getConstructSignatures();
      const props = t.getProperties();
      const idx = t.getIndexInfos();
      // A named, non-inline type is emitted as a named ref with args; its body is requested only on demand.
      if (nm && depth > 0 && (of & (OF.Interface | OF.Class | OF.Reference)) && !(calls.length && !props.length)) {
        const args = (of & OF.Reference) ? checker.getTypeArguments(t) : (t.getAliasTypeArguments?.() ?? []);
        return { kind: 'named', name: nm.name, args: args.map((a) => conv(a, depth + 1, seen2)) };
      }
      if (calls.length && !props.length && !idx.length) {
        if (calls.length === 1) return fnJson(calls[0], depth, seen2);
        return { kind: 'overloaded', signatures: calls.map((s) => fnJson(s, depth, seen2)) };
      }
      if (depth > 0 && props.length > MAX_FIELDS) { bump('truncatedObjects'); return { kind: 'named', name: nm?.name ?? '(anonymous)', args: [], truncated: props.length }; }
      const fields = props.map((p) => {
        const pt = checker.getTypeOfSymbol(p);
        return { name: p.name, type: conv(pt, depth + 1, seen2), required: !(p.flags & SF.Optional), accessor: (p.flags & (SF.GetAccessor | SF.SetAccessor)) ? true : undefined, method: (p.flags & SF.Method) ? true : undefined };
      });
      const indexes = idx.map((i) => ({ key: conv(i.keyType, depth + 1, seen2), value: conv(i.valueType, depth + 1, seen2), readonly: i.isReadonly }));
      const o = { kind: 'objectType', fields };
      if (indexes.length) o.indexes = indexes;
      if (calls.length) o.calls = calls.length;
      if (nm) o.name = nm.name;
      if (of & OF.Mapped) o.mapped = true;
      return o;
    }
    return { kind: 'opaque', reason: 'flags ' + f };
  }
  return { conv };
}

