239	/// How the checker prints one parameter of a function type: `name?: T` is optional, `...name: T[]` is the rest
240	/// parameter.
241	#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
242	pub(crate) struct Marker {
243	    pub optional: bool,
244	    pub rest: bool,
245	}
246	
247	/// The markers of the parameters of a function type as the checker prints it, `(percent?: number, ...rest: string[])
248	/// => string`, one per parameter in order. `None` when the text is not a parameter list that can be read to its end
249	/// (a long type is cut short with `...`).
250	pub(crate) fn parameter_markers(text: &str) -> Option<Vec<Marker>> {
251	    let chars: Vec<char> = text.chars().collect();
252	    // Type parameters come first: `<T>(value: T) => T`.
253	    let open = if chars.first() == Some(&'<') { matching_close(&chars, 0)? + 1 } else { 0 };
254	    if chars.get(open) != Some(&'(') {
255	        return None;
256	    }
257	    let close = matching_close(&chars, open)?;
258	    let list = chars.get(open + 1..close)?;
259	    if list.iter().all(|c| c.is_whitespace()) {
260	        return Some(Vec::new());
261	    }
262	    top_level_segments(list)?.into_iter().map(parameter_marker).collect()
263	}
264	
265	fn parameter_marker(parameter: &[char]) -> Option<Marker> {
266	    let text: String = parameter.iter().collect();
267	    let text = text.trim_start();
268	    let (rest, text) = match text.strip_prefix("...") {
269	        Some(after) => (true, after),
270	        None => (false, text),
271	    };
272	    // The name: an identifier, or `__0` for a destructured parameter. Whatever follows it, `?` marks it optional.
273	    let after_name = text.trim_start_matches(|c: char| c.is_alphanumeric() || c == '_' || c == '$');
274	    if after_name.len() == text.len() {
275	        return None;
276	    }
277	    Some(Marker { optional: after_name.starts_with('?'), rest })
278	}
279	
280	/// The parts of a parameter list between its top-level commas.
281	fn top_level_segments(list: &[char]) -> Option<Vec<&[char]>> {
282	    let mut segments = Vec::new();
283	    let (mut start, mut i) = (0, 0);
284	    while i < list.len() {
285	        match list.get(i)? {
286	            '"' | '\'' | '`' => i = skip_string(list, i)?,
287	            '(' | '[' | '{' | '<' => i = matching_close(list, i)?,
288	            '=' if list.get(i + 1) == Some(&'>') => i += 1,
289	            ',' => {
290	                segments.push(list.get(start..i)?);
291	                start = i + 1;
292	            }
293	            _ => {}
294	        }
295	        i += 1;
296	    }
297	    segments.push(list.get(start..)?);
298	    Some(segments)
299	}
300	
301	/// The index of the bracket that closes the one at `open`, skipping strings and the `>` of `=>`.
302	fn matching_close(chars: &[char], open: usize) -> Option<usize> {
303	    let mut depth = 0usize;
304	    let mut i = open;
305	    while i < chars.len() {
306	        match chars.get(i)? {
307	            '"' | '\'' | '`' => i = skip_string(chars, i)?,
308	            '=' if chars.get(i + 1) == Some(&'>') => i += 1,
309	            '(' | '[' | '{' | '<' => depth += 1,
310	            ')' | ']' | '}' | '>' => {
311	                depth = depth.checked_sub(1)?;
312	                if depth == 0 {
313	                    return Some(i);
314	                }
315	            }
316	            _ => {}
317	        }
318	        i += 1;
319	    }
320	    None
321	}
322	
323	/// The index of the quote that closes the string, or template literal, that starts at `open`.
324	fn skip_string(chars: &[char], open: usize) -> Option<usize> {
325	    let quote = *chars.get(open)?;
326	    let mut i = open + 1;
327	    while i < chars.len() {
328	        match chars.get(i)? {
329	            '\\' => i += 1,
330	            c if *c == quote => return Some(i),
331	            '$' if quote == '`' && chars.get(i + 1) == Some(&'{') => i = matching_close(chars, i + 1)?,
332	            _ => {}
333	        }
334	        i += 1;
335	    }
336	    None
337	}
