351	mod tests {
352	    use super::*;
353	
354	    const REQUIRED: Marker = Marker { optional: false, rest: false };
355	    const OPTIONAL: Marker = Marker { optional: true, rest: false };
356	    const REST: Marker = Marker { optional: false, rest: true };
357	
358	    #[test]
359	    fn a_printed_signature_gives_one_marker_per_parameter() {
360	        let cases: [(&str, Vec<Marker>); 6] = [
361	            ("() => void", vec![]),
362	            ("(a: number) => void", vec![REQUIRED]),
363	            ("(percent?: number, ...rest: string[]) => string", vec![OPTIONAL, REST]),
364	            ("(...args: any[]) => void", vec![REST]),
365	            ("(a: number, b?: string) => void", vec![REQUIRED, OPTIONAL]),
366	            // `undefined` in the type is not the `?` marker.
367	            ("(a: number, b: string | undefined) => void", vec![REQUIRED, REQUIRED]),
368	        ];
369	        for (text, expected) in cases {
370	            assert_eq!(parameter_markers(text), Some(expected), "{text}");
371	        }
372	    }
373	
374	    #[test]
375	    fn markers_inside_a_parameter_type_are_not_the_parameters() {
376	        let cases: [(&str, Vec<Marker>); 5] = [
377	            ("(handler: (a?: number, ...b: string[]) => void, c?: string) => void", vec![REQUIRED, OPTIONAL]),
378	            ("(options: { a?: number; b: string }, c?: boolean) => void", vec![REQUIRED, OPTIONAL]),
379	            ("(pair: [first?: string, second?: number], ...more: Array<string>) => void", vec![REQUIRED, REST]),
380	            // Commas and brackets inside a string literal or a template literal type.
381	            ("(key: \"a,b\" | 'c)', template?: `--${string}`) => void", vec![REQUIRED, OPTIONAL]),
382	            ("(map: Map<string, Array<number>>, last?: number) => void", vec![REQUIRED, OPTIONAL]),
383	        ];
384	        for (text, expected) in cases {
385	            assert_eq!(parameter_markers(text), Some(expected), "{text}");
386	        }
387	    }
