426	impl std::fmt::Display for CallError {
427	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
428	        match self {
429	            CallError::Fatal(message) | CallError::Rejected(message) => f.write_str(message),
430	        }
431	    }
432	}
433	
434	fn classify(error: TscClientError) -> CallError {
435	    match error {
436	        TscClientError::RpcError { message, .. } => CallError::Rejected(message),
437	        other => CallError::Fatal(other.to_string()),
438	    }
439	}
