455	/// The checker keeps a symbol's name in an escaped form: a name that starts with two underscores gets a third
456	/// (`escapeLeadingUnderscores`), so that it cannot collide with its own internal names such as `__call`. The source
457	/// writes `__size`, the checker answers `___size`. A name with fewer than three leading underscores is unchanged, and
458	/// so are the internal names, which start with exactly two.
459	pub(crate) fn unescape_leading_underscores(name: &str) -> &str {
460	    if name.starts_with("___") { name.strip_prefix('_').unwrap_or(name) } else { name }
461	}
462	
463	fn unescaped_name<'de, D: serde::Deserializer<'de>>(deserializer: D) -> Result<String, D::Error> {
464	    let name = String::deserialize(deserializer)?;
465	    Ok(unescape_leading_underscores(&name).to_string())
466	}
