529	/// One `tsc --api` session bound to a snapshot and project.
530	pub(crate) struct Rpc {
531	    client: Client,
532	    deadline: Duration,
533	    snapshot: u64,
534	    project: String,
535	    /// Every call and its answer, when the caller asked to record a replay fixture.
536	    recording: Option<Mutex<Vec<Value>>>,
537	    calls: Mutex<BTreeMap<String, u64>>,
538	}
539	
540	impl Rpc {
541	    pub(crate) async fn open(
542	        client: Client,
543	        deadline: Duration,
544	        tsconfig: Option<&str>,
545	        root_files: &[String],
546	        record: bool,
547	    ) -> Result<Rpc, CallError> {
548	        let options = Rpc::prepare(&client, deadline, tsconfig).await?;
549	        Rpc::open_with(client, deadline, &options, root_files, record).await
550	    }
551	
552	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
553	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
554	    /// numeric ones.
555	    pub(crate) async fn prepare(
556	        client: &Client,
557	        deadline: Duration,
558	        tsconfig: Option<&str>,
559	    ) -> Result<Value, CallError> {
560	        let rpc = Rpc {
561	            client: client.clone(),
562	            deadline,
563	            snapshot: 0,
564	            project: String::new(),
565	            recording: None,
566	            calls: Mutex::new(BTreeMap::new()),
567	        };
568	        rpc.call("initialize", Value::Null).await?;
569	        Ok(match tsconfig {
570	            Some(file) => {
571	                let parsed = rpc.call("parseConfigFile", json!({ "file": file })).await?;
572	                parsed.get("options").cloned().unwrap_or_else(default_options)
573	            }
574	            None => default_options(),
575	        })
576	    }
577	
578	    /// A snapshot over `root_files` in a session [`Rpc::prepare`] already initialized.
579	    pub(crate) async fn open_with(
580	        client: Client,
581	        deadline: Duration,
582	        options: &Value,
583	        root_files: &[String],
584	        record: bool,
585	    ) -> Result<Rpc, CallError> {
586	        let mut rpc = Rpc {
587	            client,
588	            deadline,
589	            snapshot: 0,
590	            project: String::new(),
591	            recording: record.then(|| Mutex::new(Vec::new())),
592	            calls: Mutex::new(BTreeMap::new()),
593	        };
594	        let created = rpc
595	            .call(
596	                "createSnapshot",
597	                json!({ "createPrograms": [{ "rootFiles": root_files, "compilerOptions": options }] }),
598	            )
599	            .await?;
600	        let response: SnapshotResponse = decode(created)?;
601	        let project = response
602	            .projects
603	            .into_iter()
604	            .next()
605	            .ok_or_else(|| CallError::Rejected("createSnapshot returned no project".to_string()))?;
606	        rpc.snapshot = response.snapshot;
607	        rpc.project = project.id;
608	        Ok(rpc)
609	    }
610	
611	    pub(crate) async fn release(&self) {
612	        self.call("release", json!({ "snapshot": self.snapshot })).await.ok();
613	    }
614	
615	    /// The recorded calls as a JSON array, or `None` when recording was off.
616	    pub(crate) fn recording(&self) -> Option<Value> {
617	        let log = self.recording.as_ref()?.lock().ok()?;
618	        Some(Value::Array(log.clone()))
619	    }
620	
621	    /// Requests sent so far, by method.
622	    pub(crate) fn calls(&self) -> BTreeMap<String, u64> {
623	        self.calls.lock().map(|calls| calls.clone()).unwrap_or_default()
624	    }
625	
626	    async fn call(&self, method: &str, params: Value) -> Result<Value, CallError> {
627	        if let Ok(mut calls) = self.calls.lock() {
628	            *calls.entry(method.to_string()).or_default() += 1;
629	        }
630	        let answer = self.client.request(method, params.clone(), self.deadline).await.map_err(classify)?;
631	        if let Some(log) = &self.recording
632	            && let Ok(mut log) = log.lock()
633	        {
634	            log.push(json!({ "method": method, "params": params, "result": answer.value }));
635	        }
636	        Ok(answer.value)
637	    }
638	
639	    async fn scoped<T: DeserializeOwned>(&self, method: &str, extra: Value) -> Result<T, CallError> {
640	        let mut params = json!({ "snapshot": self.snapshot, "project": self.project });
641	        if let (Some(base), Value::Object(extra)) = (params.as_object_mut(), extra) {
642	            base.extend(extra);
643	        }
644	        decode(self.call(method, params).await?)
645	    }
646	
647	    pub(crate) async fn source_file_symbol(&self, file: &str) -> Result<Option<SymbolInfo>, CallError> {
648	        self.scoped("getSymbolOfSourceFile", json!({ "file": file })).await
649	    }
650	
651	    pub(crate) async fn exports_of_module(&self, module: &Value) -> Result<Vec<SymbolInfo>, CallError> {
652	        self.scoped("getExportsOfModule", json!({ "symbol": module })).await
653	    }
654	
655	    /// Only for symbols flagged `Alias`: the beta panics on a plain `default` export.
656	    pub(crate) async fn aliased_symbol(&self, symbol: &Value) -> Result<SymbolInfo, CallError> {
657	        self.scoped("getAliasedSymbol", json!({ "symbol": symbol })).await
658	    }
659	
660	    pub(crate) async fn type_of_symbol(&self, symbol: &Value) -> Result<TypeInfo, CallError> {
661	        self.scoped("getTypeOfSymbol", json!({ "symbol": symbol })).await
662	    }
663	
664	    pub(crate) async fn types_of_symbols(&self, symbols: &[&Value]) -> Result<Vec<TypeInfo>, CallError> {
665	        self.scoped("getTypesOfSymbols", json!({ "symbols": symbols })).await
666	    }
667	
668	    pub(crate) async fn signatures(&self, type_id: u64) -> Result<Vec<SignatureInfo>, CallError> {
669	        self.scoped("getSignaturesOfType", json!({ "type": type_id, "kind": 0 })).await
670	    }
671	
672	    pub(crate) async fn parameters(&self, signature: u64) -> Result<Vec<SymbolInfo>, CallError> {
673	        self.scoped("getParametersOfSignature", json!({ "objectId": signature })).await
674	    }
675	
676	    pub(crate) async fn return_type(&self, signature: u64) -> Result<TypeInfo, CallError> {
677	        self.scoped("getReturnTypeOfSignature", json!({ "objectId": signature })).await
678	    }
679	
680	    pub(crate) async fn properties(&self, type_id: u64) -> Result<Vec<SymbolInfo>, CallError> {
681	        self.scoped("getPropertiesOfType", json!({ "type": type_id })).await
682	    }
683	
684	    pub(crate) async fn members(&self, type_id: u64) -> Result<Vec<TypeInfo>, CallError> {
685	        self.scoped("getTypesOfType", json!({ "objectId": type_id })).await
686	    }
687	
688	    pub(crate) async fn type_arguments(&self, type_id: u64) -> Result<Vec<TypeInfo>, CallError> {
689	        self.scoped("getTypeArguments", json!({ "type": type_id })).await
690	    }
691	
692	    pub(crate) async fn is_array(&self, type_id: u64) -> Result<bool, CallError> {
693	        self.scoped("isArrayType", json!({ "type": type_id })).await
694	    }
695	
696	    pub(crate) async fn alias_symbol(&self, type_id: u64) -> Result<Option<SymbolInfo>, CallError> {
697	        self.scoped("getAliasSymbolOfType", json!({ "objectId": type_id })).await
698	    }
699	
700	    pub(crate) async fn type_to_string(&self, type_id: u64) -> Result<String, CallError> {
701	        self.scoped("typeToString", json!({ "type": type_id })).await
702	    }
703	
704	    pub(crate) async fn documentation(&self, symbol: &Value) -> Result<String, CallError> {
705	        self.scoped("getDocumentationComment", json!({ "symbol": symbol })).await
706	    }
707	}
708	
709	fn default_options() -> Value {
710	    // Numeric enum values: JSX preserve, ESNext modules, bundler resolution, ES2022.
711	    json!({ "jsx": 1, "module": 99, "moduleResolution": 100, "target": 9, "strict": true, "skipLibCheck": true, "noEmit": true })
712	}
713	
714	fn decode<T: DeserializeOwned>(value: Value) -> Result<T, CallError> {
715	    serde_json::from_value(value).map_err(|error| CallError::Rejected(format!("unexpected response shape: {error}")))
716	}
717	
